SELECT [salesterritory].[countryregioncode] AS [country], COUNT([salesorderheader].[salesorderid]) AS [order_count] FROM [sales].[salesorderheader] LEFT JOIN [sales].[salesterritory] ON [sales].[salesorderheader].[territoryid] = [sales].[salesterritory].[territoryid] WHERE [salesorderheader].[orderdate] >= @p1 GROUP BY [salesterritory].[countryregioncode] ORDER BY [order_count] DESC OFFSET 0 ROWS FETCH NEXT 100 ROWS ONLY